import{z as B,x as d,o as r,c as i,q as s,j as l,D as A,d as e,s as o,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"地址空间布局","description":"","frontmatter":{"title":"地址空间布局","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/addrspace-layout.md","filePath":"cs/addrspace-layout.md","lastUpdated":1791063341000}'),p={name:"cs/addrspace-layout.md"};function m(c,a,D,u,C,h){const t=d("Mermaid");return r(),i("div",null,[a[2]||(a[2]=s('<h1 id="地址空间布局" tabindex="-1">地址空间布局 <a class="header-anchor" href="#地址空间布局" aria-label="Permalink to &quot;地址空间布局&quot;">​</a></h1><div class="epigraph"><p>每个进程看见一段自己的虚地址：代码、数据、堆向高处长，栈向低处长；内核通常另有映射。</p><footer>—— 据 Tanenbaum and Bos, Modern Operating Systems；Silberschatz et al. 整理</footer></div><p><a href="/cs/lock-ordering">上一课</a>把同步与死锁回避收束。<a href="/cs/process-image">进程映像</a>只说「有一份地址空间」，还没有画出用户虚地址里各段放哪。<a href="/cs/paging-vm">分页</a>已能把任意虚页接到物理页，本课不重导页表，只规定<strong>布局惯例</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>加载器把代码放进内存后，堆从哪长、栈从哪长、共享库映射到哪，若没有约定，编译器生成的绝对地址与 <code>brk</code>/<code>mmap</code> 会对撞。缺口不是 TLB 怎么填，而是用户空间的分区：只读文本、已初始化数据、BSS、堆、栈、以及稍后的内存映射区。内核空间是否映射进每个进程，是同一张图的上半或另半，本课点名即可。</p><p>本课不把 ASLR 的随机化分布写成安全课。</p><p><span class="marginnote">经典 Unix：低地址文本，之上数据与堆，高用户地址栈。Linux 用户/内核分界随架构而变；对象仍是「一段用户可用虚区间」。</span></p><p><span class="marginnote">术语翻译：BSS（Block Started by Symbol）是「没有显式赋初值的全局变量」住的段。编译器不把它们的零值写进可执行文件，只在加载时划一块内存统一清零——所以 <code>int a[1000000];</code> 不会让程序文件变大一倍，却会让进程内存变大 4 MB。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>链接器给出段的虚地址；内核为进程建页表，把合法区间标成可读/写/执行。<a href="/cs/load-dynlink">加载</a>已谈重定位；本课只要求：堆通过 <code>brk</code> 或匿名映射向高地址扩展，栈在故障时可向下扩一页（直到资源上限）。空洞（未映射）访问走缺页异常，下一课才说是立刻分配还是拒绝。</p>',10)),(r(),l(n,null,{default:A(()=>[o(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20TEXT%5B%22%E6%96%87%E6%9C%AC%22%5D%20--%3E%20DATA%5B%22%E6%95%B0%E6%8D%AE%E4%B8%8E%20BSS%22%5D%0A%20%20DATA%20--%3E%20HEAP%5B%22%E5%A0%86%E5%90%91%E4%B8%8A%22%5D%0A%20%20STACK%5B%22%E6%A0%88%E5%90%91%E4%B8%8B%22%5D%20--%3E%20MAP%5B%22%E6%98%A0%E5%B0%84%E5%8C%BA%3A%20%E5%90%8E%E8%AF%BE%20mmap%22%5D%0A%20%20HEAP%20--%3E%20HOLE%5B%22%E6%9C%AA%E6%98%A0%E5%B0%84%E7%A9%BA%E6%B4%9E%22%5D%0A%20%20STACK%20--%3E%20HOLE%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"数字实例：一页通常是 4 KB。栈第一次被碰到底部时，缺页处理只向下补一页 4 KB，而不是按上限（常见 8 MB）一次性提交——这就是「可向下扩一页」省钱的地方：程序真用了多少栈，才占多少物理内存。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[e("布局把「映像」变成可检查的区间集合：栈溢出是碰到守卫页或碰到堆，而不是神秘写坏内核——用户写不进内核页，靠的是分页权限，不是本课新硬件。线程各有栈，仍落在同一布局的不同区间，与"),E("a",{href:"/cs/thread-shared-addr"},"共享地址空间"),e("一致。")],-1)),a[6]||(a[6]=E("p",null,"内核映射若出现在每个进程的高半，系统调用路径上内核才能用自己的指针；用户仍不可执行那些页上的内核代码当用户指令。",-1)),a[7]||(a[7]=E("p",null,"上图的布局回答「各段放在哪」，下面这张回答另一个问题：一次具体的内存访问，如何被布局与权限逐层判定。",-1)),(r(),l(n,null,{default:A(()=>[o(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22CPU%20%E8%AE%BF%E9%97%AE%E4%B8%80%E4%B8%AA%E8%99%9A%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20B%7B%22%E8%AF%A5%E9%A1%B5%E5%9C%A8%E9%A1%B5%E8%A1%A8%E4%B8%AD%E6%9C%89%E6%95%88%3F%22%7D%0A%20%20B%20--%20%22%E5%90%A6%22%20--%3E%20C%5B%22%E8%A7%A6%E5%8F%91%E7%BC%BA%E9%A1%B5%E5%BC%82%E5%B8%B8%22%5D%0A%20%20C%20--%3E%20D%7B%22%E5%9C%B0%E5%9D%80%E8%90%BD%E5%9C%A8%E5%90%88%E6%B3%95%E5%8C%BA%E9%97%B4%3F%22%7D%0A%20%20D%20--%20%22%E6%98%AF%3A%20%E7%A9%BA%E6%B4%9E%E6%88%96%E6%A0%88%E5%BA%95%22%20--%3E%20E%5B%22%E8%A1%A5%E9%A1%B5%E6%88%96%E6%89%A9%E6%A0%88%E5%90%8E%E9%87%8D%E8%AF%95%22%5D%0A%20%20D%20--%20%22%E5%90%A6%3A%20%E9%87%8E%E6%8C%87%E9%92%88%22%20--%3E%20F%5B%22%E6%AE%B5%E9%94%99%E8%AF%AF%2C%20%E7%BB%88%E6%AD%A2%E8%BF%9B%E7%A8%8B%22%5D%0A%20%20B%20--%20%22%E6%98%AF%22%20--%3E%20G%7B%22%E8%AF%BB%2F%E5%86%99%2F%E6%89%A7%E8%A1%8C%E6%9D%83%E9%99%90%E5%85%81%E8%AE%B8%3F%22%7D%0A%20%20G%20--%20%22%E5%85%81%E8%AE%B8%22%20--%3E%20H%5B%22%E5%AE%8C%E6%88%90%E8%BF%99%E6%AC%A1%E8%AE%BF%E9%97%AE%22%5D%0A%20%20G%20--%20%22%E4%B8%8D%E5%85%81%E8%AE%B8%2C%20%E5%A6%82%E5%86%99%E6%96%87%E6%9C%AC%E6%AE%B5%22%20--%3E%20F%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=s('<p><span class="marginnote">直觉类比：把地址空间想成一栋按楼层出租的大楼——文本层只许参观（读）、不许涂改（写）；堆和数据的房间可以自由布置；楼层之间的大片空置区不是你的，闯进去保安（缺页处理）会来，先看你是不是合法租户越界了，再决定补房间还是赶人。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 32 位 3G/1G 与 64 位 canonical 地址的全部数字，不把 vsyscall 页写进主干。也不把文件映射的空洞策略提前：那是 mmap 课。安全栏的 NX 与 ASLR 用本课的段权限当前提，本课不讲攻击。</p><p>共享库的 PIC 文本可被多进程映射到不同虚地址；物理帧仍可共享，这是后课 mmap 的伏笔。</p><p>后课默认：用户虚空间有文本、数据、堆、栈和空洞。空洞何时因访问而变成有效页，下一课按需调页。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>进程映像的虚地址按段布局；堆与栈相对生长。</li><li>页表权限执行布局；本课不重导页表。</li><li>未映射页的补页策略是按需调页的缺口。</li><li>出处：Tanenbaum and Bos, <em>MOS</em>；Silberschatz et al., <em>OSC</em>。</li></ul>',7))])}const T=B(p,[["render",m]]);export{S as __pageData,T as default};
